        "code": "# === PHAN 1: Cap nhat .codex/config.toml (thay gpt-5.2-codex da deprecated) ===\n# model = \"gpt-5.6-terra\"        # Thay cho \"gpt-5.2-codex\" (retired)\n# model_reasoning_effort = \"medium\"\n# sandbox_mode = \"workspace-write\"\n# approval_policy = \"on-request\"  # Khong dung \"untrusted\" (da bi xoa o Codex CLI v0.149.0)\n\n# === PHAN 2: Script Python chay Sprint Task tren Gemini 3.8 Flash ===\nimport os\nfrom google import genai\nfrom google.genai import types\n\nALLOWED_FLASH38_THINKING = {\"low\", \"medium\", \"high\"}\nclient = genai.Client(api_key=os.environ[\"GEMINI_API_KEY\"])\n\ndef run_flash38_sprint_task(prompt: str, level: str = \"medium\") -> str:\n    # Chot chan: Gemini 3.8 Flash se tra ve loi API neu truyen 'minimal'\n    safe_level = level if level in ALLOWED_FLASH38_THINKING else \"low\"\n\n    response = client.models.generate_content(\n        model=\"gemini-3.8-flash\",\n        contents=prompt,\n        config=types.GenerateContentConfig(\n            thinking_config=types.ThinkingConfig(thinking_level=safe_level),\n            max_output_tokens=32768,\n        ),\n    )\n    return response.text\n"
