        "code": "import time\nfrom google import genai\n\n# Bat buoc google-genai >= 3.2.0 (v1 GA cho Interactions; v1beta cho Agents/Decisions)\nclient = genai.Client()\n\n# 1) Stateful conversation voi Gemini 3.8 Flash (KHONG truyen temperature, KHONG dung minimal)\nturn1 = client.interactions.create(\n    model=\"gemini-3.8-flash\",\n    input=\"Phan tich kien truc bang phan quyen RLS cho module Cong no MISA.\",\n    system_instruction=\"Ban la Solution Architect cua DOMATION.\",\n    generation_config={\"thinking_level\": \"medium\", \"max_output_tokens\": 8192}\n)\nturn2 = client.interactions.create(\n    model=\"gemini-3.8-flash\",\n    input=\"Viet file migration PostgreSQL kem policy FORCE ROW LEVEL SECURITY.\",\n    previous_interaction_id=turn1.id,\n    system_instruction=\"Ban la Solution Architect cua DOMATION.\",\n    generation_config={\"thinking_level\": \"high\"}\n)\n\n# 2) Long Decode > 65.536 token tren Gemini 4 Argon (bat buoc background=True + store=True)\nlong_job = client.interactions.create(\n    model=\"gemini-4-argon\",\n    input=\"Sinh tron bo tai lieu dac ta OpenAPI va test suite cho 12 phan he ERP 5.0.\",\n    background=True,\n    store=True,\n    generation_config={\"thinking_level\": \"high\", \"max_output_tokens\": 180000}\n)\nwhile True:\n    status_obj = client.interactions.get(long_job.id)\n    if status_obj.status == \"completed\":\n        print(status_obj.output_text)\n        break\n    if status_obj.status in (\"failed\", \"cancelled\"):\n        raise RuntimeError(f\"Argon background failed: {status_obj.status}\")\n    time.sleep(5)\n\n# --- Mau .gemini/policies/domation-erp.toml (Uu tien Workspace Tier 3 < User 4 < Admin 5) ---\n# [[rule]]\n# toolName = \"run_shell_command\"\n# commandPrefix = \"psql\"\n# decision = \"ask_user\"\n# priority = 300\n#\n# [[rule]]\n# toolName = \"run_shell_command\"\n# commandPrefix = \"rm -rf\"\n# decision = \"deny\"\n# priority = 500\n"
